import uuid


class Queue:
    """Thread-safe in-memory job queue with lease fencing.

    All mutating operations are guarded by a single lock so that claim/renew/
    complete are atomic.  Times are injected via the ``now`` argument; no
    sleeps or real clocks are used.
    """

    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}      # job_id -> {'state', 'worker', 'token', 'expiry'}
        self._order = []     # job ids in insertion order

    def add(self, job_id):
        with self._lock:
            if job_id in self._jobs:
                return
            self._jobs[job_id] = {'state': 'queued'}

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            for job_id in self._order:
                job = self._jobs.get(job_id)
                if job is None or job['state'] == 'done':
                    continue
                if job['state'] == 'queued':
                    job['state'] = 'running'
                    job['worker'] = worker
                    job['token'] = self._new_token()
                    job['expiry'] = now + ttl
                    return {'job_id': job_id, 'worker': worker,
                            'token': job['token']}
                # Running job whose lease has expired may be fenced out.
                if job['expiry'] <= now:
                    job['state'] = 'running'
                    job['worker'] = worker
                    job['token'] = self._new_token()
                    job['expiry'] = now + ttl
                    return {'job_id': job_id, 'worker': worker,
                            'token': job['token']}
            return None

    def renew(self, lease, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            job = self._jobs.get(lease['job_id'])
            if job is None or job['state'] != 'running':
                return False
            if job['token'] != lease['token'] or job['worker'] != lease['worker']:
                return False
            if job['expiry'] <= now:
                return False
            job['expiry'] = now + ttl
            return True

    def complete(self, lease, now):
        with self._lock:
            job = self._jobs.get(lease['job_id'])
            if job is None or job['state'] != 'running':
                return False
            if job['token'] != lease['token'] or job['worker'] != lease['worker']:
                return False
            if job['expiry'] <= now:
                return False
            job['state'] = 'done'
            return True

